package io.github.diodeme.ji.standalone;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

final class StandaloneResourcesTest {
    @Test
    void runtimeClasspathContainsBuiltWebShellAndPwaAssets() {
        assertNotNull(JiStandalone.class.getResource("/web/index.html"));
        assertNotNull(JiStandalone.class.getResource("/web/manifest.webmanifest"));
        assertNotNull(JiStandalone.class.getResource("/web/sw.js"));
    }

    @Test
    void standaloneEntryDoesNotReferenceNodeAtRuntime() throws Exception {
        String source;
        try (var input = JiStandalone.class.getResourceAsStream("JiStandalone.class")) {
            assertNotNull(input);
            source = new String(input.readAllBytes(), java.nio.charset.StandardCharsets.ISO_8859_1);
        }
        assertTrue(!source.contains("node") && !source.contains("pnpm") && !source.contains("vite"));
    }
}
